{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C14"],
      "claim": "Fisetin, the closest structural analogue, showed 44.1% oral bioavailability in patients, directly exceeding the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Apigenin was reported to be bioavailable at 20% and 30% after oral dosing, meeting the F>=20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Gallium maltolate, a small methyl-hydroxypyrone complex, provided 25–57% oral bioavailability in healthy humans, supporting that small pyrone/coumarin-like molecules can exceed 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Chrysin, a dihydroxyflavone, had estimated oral bioavailability of only 0.003–0.02% in humans, but this low value comes from a larger polyphenolic flavonoid with poor solubility and extensive conjugation.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C35"],
      "claim": "Quercetin, a pentahydroxyflavone, had absolute oral bioavailability of 0.64% in healthy adults, reflecting the poor absorption of highly polyphenolic flavonoids rather than the query's smaller monohydroxy coumarin structure.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "low",
  "decision_summary": "The query is a small monohydroxy coumarin, structurally distinct from the polyphenolic flavonoids that dominate the low-bioavailability evidence. The closest numeric analogue, fisetin, reached 44.1% oral bioavailability, apigenin was positive at 20–30%, and a small pyrone complex showed 25–57% oral bioavailability. The abundant low values come from larger, more polar flavonoids with multiple phenolic groups and poor solubility, features not shared by the query. Therefore, F>=20% is better supported, though with low confidence due to limited structural transferability.",
  "evidence_gaps": [
    "No direct human absolute oral bioavailability data for 4-methylumbelliferone (the query).",
    "Most evidence comes from flavonoids with multiple hydroxyl groups and larger size, limiting transferability to the query.",
    "The extent of first-pass glucuronidation/sulfation for the query is uncertain."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

